python3 - <<'PY'
import json, glob
seen = set(); tot = {}; n = 0; dupes = 0
for f in sorted(glob.glob('/root/.claude/projects/*/*.jsonl')):
    for line in open(f):
        d = json.loads(line)
        m = d.get('message') or {}
        u = m.get('usage')
        if not u: continue
        mid = m.get('id')
        if mid in seen:
            dupes += 1; continue
        seen.add(mid); n += 1
        for k in ('input_tokens','cache_creation_input_tokens','cache_read_input_tokens','output_tokens'):
            tot[k] = tot.get(k,0) + u.get(k,0)
        td = u.get('output_tokens_details') or {}
        tot['thinking_tokens'] = tot.get('thinking_tokens',0) + td.get('thinking_tokens',0)
        cc = u.get('cache_creation') or {}
        for k in ('ephemeral_1h_input_tokens','ephemeral_5m_input_tokens'):
            tot[k] = tot.get(k,0) + cc.get(k,0)
print('unique assistant messages:', n, '| duplicate lines skipped:', dupes)
print(json.dumps(tot, indent=2))
PY

