import assert from 'node:assert/strict';
import { test } from 'node:test';
import { parsePrices, summariseTranscript } from './session-cost.ts';

const prices = parsePrices(
  JSON.stringify({
    as_of: '2026-01-01',
    rates: {
      'test-model/standard': {
        input: 1,
        output: 10,
        cache_write_5m: 2,
        cache_write_1h: 4,
        cache_read: 0.5,
      },
      'test-model/fast': {
        input: 2,
        output: 20,
        cache_write_5m: 4,
        cache_write_1h: 8,
        cache_read: 1,
      },
    },
  }),
);

type UsageOverrides = {
  id?: string;
  speed?: string;
  model?: string;
  sidechain?: boolean;
  input?: number;
  output?: number;
  thinking?: number;
  read?: number;
  write5m?: number;
  write1h?: number;
  written?: number;
};

const response = (overrides: UsageOverrides = {}): string =>
  JSON.stringify({
    type: 'assistant',
    sessionId: 'sess',
    gitBranch: 'a-branch',
    timestamp: '2026-03-04T05:06:07.000Z',
    isSidechain: overrides.sidechain ?? false,
    message: {
      id: overrides.id ?? 'msg_1',
      model: overrides.model ?? 'test-model',
      usage: {
        input_tokens: overrides.input ?? 0,
        output_tokens: overrides.output ?? 0,
        cache_read_input_tokens: overrides.read ?? 0,
        cache_creation_input_tokens:
          overrides.written ?? (overrides.write5m ?? 0) + (overrides.write1h ?? 0),
        cache_creation: {
          ephemeral_5m_input_tokens: overrides.write5m ?? 0,
