toolUseResult.originalFile:
// Prices a Claude Code transcript at Claude API rates. Shared by the `Stop`
// hook, which prices one session, and `scripts/costs-report.ts`, which sums
// the rows those runs leave behind.
//
// Two properties of the transcript decide the shape of everything here:
// one API response is written as several records — one per content block —
// each carrying that response's whole `usage`, so records are deduplicated by
// `message.id`; and a response is billed at the rates for its `(model, speed)`
// pair, with cache writes billed by TTL.

import { z } from 'zod';

const RateSet = z.object({
  input: z.number(),
  output: z.number(),
  cache_write_5m: z.number(),
  cache_write_1h: z.number(),
  cache_read: z.number(),
});

const PriceTableSchema = z.object({
  as_of: z.string(),
  rates: z.record(z.string(), RateSet),
});

export type Rates = z.infer<typeof RateSet>;
export type PriceTable = z.infer<typeof PriceTableSchema>;

export const parsePrices = (json: string): PriceTable =>
  PriceTableSchema.parse(JSON.parse(json));

const UsageSchema = z.object({
  input_tokens: z.number(),
  output_tokens: z.number(),
  cache_creation_input_tokens: z.number().optional(),
  cache_read_input_tokens: z.number().optional(),
  speed: z.string().optional(),
  output_tokens_details: z.object({ thinking_tokens: z.number().optional() }).optional(),
  cache_creation: z
    .object({
      ephemeral_5m_input_tokens: z.number().optional(),
      ephemeral_1h_input_tokens: z.number().optional(),
    })
    .optional(),
});

const ResponseRecordSchema = z.object({
  sessionId: z.string().optional(),
  gitBranch: z.string().optional(),
  cwd: z.string().optional(),
  timestamp: z.string().optional(),
  isSidechain: z.boolean().optional(),
  message: z.object({ id: z.string(), model: z.string(), usage: UsageSchema }),
});

export type TokenTally = {
  inputTokens: number;
  cacheWrite5mTokens: number;
  cacheWrite1hTokens: number;
  cacheReadTokens: number;
  outputTokens: number;
  thinkingTokens: number;
};

export type Billed = {
  responses: number;
  costUsd: number;
};

export type Tally = TokenTally & Billed;

export type SessionCost = {
  sessionId: string;
  branch: string | null;
  cwd: string | null;
  firstResponseAt: string | null;
  lastResponseAt: string | null;
  pricesAsOf: string;
  total: Tally;
  ownTurns: Tally;
  subagents: Tally;
  byRate: Record<string, Tally>;
  warnings: string[];
};

// Thinking tokens are absent: the model already counts them inside its output,
// so billing them again would double-charge every turn that thought.
const BILLED_AT = {
  inputTokens: 'input',
  cacheWrite5mTokens: 'cache_write_5m',
  cacheWrite1hTokens: 'cache_write_1h',
  cacheReadTokens: 'cache_read',
  outputTokens: 'output',
} as const satisfies Record<string, keyof Rates>;

const BILLED_FIELDS = Object.keys(BILLED_AT) as (keyof typeof BILLED_AT)[];

const TOKEN_FIELDS = [...BILLED_FIELDS, 'thinkingTokens'] as const satisfies readonly (keyof TokenTally)[];

const emptyTally = (): Tally => ({
  inputTokens: 0,
  cacheWrite5mTokens: 0,
  cacheWrite1hTokens: 0,
  cacheReadTokens: 0,
  outputTokens: 0,
  thinkingTokens: 0,
  responses: 0,
  costUsd: 0,
});

const addInto = (target: Tally, source: Tally): void => {
  for (const field of TOKEN_FIELDS) target[field] += source[field];
  target.responses += source.responses;
  target.costUsd += source.costUsd;
};

export const costOf = (tokens: TokenTally, rates: Rates): number => {
  let usd = 0;
  for (const field of BILLED_FIELDS) usd += (tokens[field] * rates[BILLED_AT[field]]) / 1e6;
  return usd;
};

/** `<model>/<speed>`, the pair a response is billed under. */
export const rateKey = (model: string, speed: string | undefined): string =>
  `${model}/${speed ?? 'standard'}`;

type Response = z.infer<typeof ResponseRecordSchema>;

const tokensOf = (response: Response, warnings: string[]): TokenTally => {
  const { usage } = response.message;
  const written = usage.cache_creation_input_tokens ?? 0;
  const split5m = usage.cache_creation?.ephemeral_5m_input_tokens ?? 0;
  const split1h = usage.cache_creation?.ephemeral_1h_input_tokens ?? 0;
  // The per-TTL split is authoritative where it accounts for the whole write.
  // Where it does not — an older record, or a shape this does not know — the
  // write bills at the 5-minute rate, which is the API's own default TTL, and
  // the discrepancy is recorded rather than rounded away.
  const trustSplit = split5m + split1h === written;
  if (!trustSplit && written > 0)
    warnings.push(
      `${response.message.id}: cache_creation split (${split5m} + ${split1h}) does not account for ${written} written tokens; billed at the 5-minute rate`,
    );
  return {
    inputTokens: usage.input_tokens,
    cacheWrite5mTokens: trustSplit ? split5m : written,
    cacheWrite1hTokens: trustSplit ? split1h : 0,
    cacheReadTokens: usage.cache_read_input_tokens ?? 0,
    outputTokens: usage.output_tokens,
    thinkingTokens: usage.output_tokens_details?.thinking_tokens ?? 0,
  };
};

/**
 * Throws when a transcript names a `(model, speed)` pair the table cannot
 * price, or an assistant record does not parse: an unpriced response silently
 * counted as free is the one failure that makes the whole ledger a lie.
 */
export const summariseTranscript = (
  jsonl: string,
  prices: PriceTable,
  fallbackSessionId: string,
): SessionCost => {
  const warnings: string[] = [];
  const seen = new Set<string>();
  const byRate: Record<string, Tally> = {};
  const total = emptyTally();
  const ownTurns = emptyTally();
  const subagents = emptyTally();
  const unpriced = new Set<string>();
  const timestamps: string[] = [];
  let sessionId: string | undefined;
  let branch: string | undefined;
  let cwd: string | undefined;

  for (const line of jsonl.split('\n')) {
    if (line.trim() === '') continue;
    const record: unknown = JSON.parse(line);
    if (!isResponseRecord(record)) continue;
    const response = ResponseRecordSchema.parse(record);
    if (seen.has(response.message.id)) continue;
    seen.add(response.message.id);

    sessionId ??= response.sessionId;
    // Last write wins: a session that renames its branch mid-flight should be
    // filed under where its work ended up, not where it started.
    branch = response.gitBranch ?? branch;
    cwd = response.cwd ?? cwd;
    if (response.timestamp !== undefined) timestamps.push(response.timestamp);

    const key = rateKey(response.message.model, response.message.usage.speed);
    const rates = prices.rates[key];
    if (rates === undefined) {
      unpriced.add(key);
      continue;
    }

    const tokens = tokensOf(response, warnings);
    const tally: Tally = { ...tokens, responses: 1, costUsd: costOf(tokens, rates) };
    addInto((byRate[key] ??= emptyTally()), tally);
    addInto(total, tally);
    addInto(response.isSidechain === true ? subagents : ownTurns, tally);
  }

  if (unpriced.size > 0)
    throw new Error(
      `No rates for ${[...unpriced].sort().join(', ')} in the price table (as of ${prices.as_of}). Add them to costs/prices.json — a response counted as free is worse than no ledger at all.`,
    );

  timestamps.sort();
  return {
    sessionId: sessionId ?? fallbackSessionId,
    branch: branch ?? null,
    cwd: cwd ?? null,
    firstResponseAt: timestamps.at(0) ?? null,
    lastResponseAt: timestamps.at(-1) ?? null,
    pricesAsOf: prices.as_of,
    total,
    ownTurns,
    subagents,
    byRate,
    warnings,
  };
};

// Records the transcript writes for other purposes — prompts, attachments, tool
// results — carry no usage and are not this module's business. Only a record
// that looks like a billed response is held to the schema.
const isResponseRecord = (record: unknown): boolean =>
  typeof record === 'object' &&
  record !== null &&
  'message' in record &&
  typeof record.message === 'object' &&
  record.message !== null &&
  'usage' in record.message;

