1	// Prices a Claude Code transcript at Claude API rates. Shared by the `Stop`
2	// hook, which prices one session, and `scripts/costs-report.ts`, which sums
3	// the rows those runs leave behind.
4	//
5	// Two properties of the transcript decide the shape of everything here:
6	// one API response is written as several records — one per content block —
7	// each carrying that response's whole `usage`, so records are deduplicated by
8	// `message.id`; and a response is billed at the rates for its `(model, speed)`
9	// pair, with cache writes billed by TTL.
10	
11	import { z } from 'zod';
12	
13	const RateSet = z.object({
14	  input: z.number(),
15	  output: z.number(),
16	  cache_write_5m: z.number(),
17	  cache_write_1h: z.number(),
18	  cache_read: z.number(),
19	});
20	
21	const PriceTableSchema = z.object({
22	  as_of: z.string(),
23	  rates: z.record(z.string(), RateSet),
24	});
25	
26	export type Rates = z.infer<typeof RateSet>;
27	export type PriceTable = z.infer<typeof PriceTableSchema>;
28	
29	export const parsePrices = (json: string): PriceTable =>
30	  PriceTableSchema.parse(JSON.parse(json));
31	
32	const UsageSchema = z.object({
33	  input_tokens: z.number(),
34	  output_tokens: z.number(),
35	  cache_creation_input_tokens: z.number().optional(),
36	  cache_read_input_tokens: z.number().optional(),
37	  speed: z.string().optional(),
38	  output_tokens_details: z
39	    .object({ thinking_tokens: z.number().optional() })
40	    .optional(),
41	  cache_creation: z
42	    .object({
43	      ephemeral_5m_input_tokens: z.number().optional(),
44	      ephemeral_1h_input_tokens: z.number().optional(),
45	    })
46	    .optional(),
47	});
48	
49	const ResponseRecordSchema = z.object({
50	  sessionId: z.string().optional(),
51	  gitBranch: z.string().optional(),
52	  cwd: z.string().optional(),
53	  timestamp: z.string().optional(),
54	  isSidechain: z.boolean().optional(),
55	  message: z.object({ id: z.string(), model: z.string(), usage: UsageSchema }),
56	});
57	
58	const TokenTallySchema = z.object({
59	  inputTokens: z.number(),
60	  cacheWrite5mTokens: z.number(),
61	  cacheWrite1hTokens: z.number(),
62	  cacheReadTokens: z.number(),
63	  outputTokens: z.number(),
64	  thinkingTokens: z.number(),
65	});
66	
67	const BilledSchema = z.object({
68	  responses: z.number(),
69	  costUsd: z.number(),
70	});
71	
72	const TallySchema = TokenTallySchema.extend(BilledSchema.shape);
73	
74	export type TokenTally = z.infer<typeof TokenTallySchema>;
75	export type Billed = z.infer<typeof BilledSchema>;
76	export type Tally = TokenTally & Billed;
77	
78	const SessionCostSchema = z.object({
79	  sessionId: z.string(),
80	  branch: z.string().nullable(),
81	  cwd: z.string().nullable(),
82	  firstResponseAt: z.string().nullable(),
83	  lastResponseAt: z.string().nullable(),
84	  pricesAsOf: z.string(),
85	  total: TallySchema,
86	  ownTurns: TallySchema,
87	  subagents: TallySchema,
88	  byRate: z.record(z.string(), TallySchema),
89	  warnings: z.array(z.string()),
90	});
91	
92	export type SessionCost = z.infer<typeof SessionCostSchema>;
93	
94	/** Rows are read back in a later process, so they are parsed rather than trusted. */
95	export const parseSessionCost = (json: string): SessionCost =>
96	  SessionCostSchema.parse(JSON.parse(json));
97	
98	// Thinking tokens are absent: the model already counts them inside its output,
99	// so billing them again would double-charge every turn that thought.
100	const BILLED_AT = {
101	  inputTokens: 'input',
102	  cacheWrite5mTokens: 'cache_write_5m',
103	  cacheWrite1hTokens: 'cache_write_1h',
104	  cacheReadTokens: 'cache_read',
105	  outputTokens: 'output',
106	} as const satisfies Record<string, keyof Rates>;
107	
108	const BILLED_FIELDS = Object.keys(BILLED_AT) as (keyof typeof BILLED_AT)[];
109	
110	const TOKEN_FIELDS = [
111	  ...BILLED_FIELDS,
112	  'thinkingTokens',
113	] as const satisfies readonly (keyof TokenTally)[];
114	
115	const emptyTally = (): Tally => ({
116	  inputTokens: 0,
117	  cacheWrite5mTokens: 0,
118	  cacheWrite1hTokens: 0,
119	  cacheReadTokens: 0,
120	  outputTokens: 0,
121	  thinkingTokens: 0,
122	  responses: 0,
123	  costUsd: 0,
124	});
125	
126	const addInto = (target: Tally, source: Tally): void => {
127	  for (const field of TOKEN_FIELDS) target[field] += source[field];
128	  target.responses += source.responses;
129	  target.costUsd += source.costUsd;
130	};
131	
132	export const costOf = (tokens: TokenTally, rates: Rates): number => {
133	  let usd = 0;
134	  for (const field of BILLED_FIELDS)
135	    usd += (tokens[field] * rates[BILLED_AT[field]]) / 1e6;
136	  return usd;
137	};
138	
139	/** `<model>/<speed>`, the pair a response is billed under. */
140	export const rateKey = (model: string, speed: string | undefined): string =>
141	  `${model}/${speed ?? 'standard'}`;
142	
143	type Response = z.infer<typeof ResponseRecordSchema>;
144	
145	const tokensOf = (response: Response, warnings: string[]): TokenTally => {
146	  const { usage } = response.message;
147	  const written = usage.cache_creation_input_tokens ?? 0;
148	  const split5m = usage.cache_creation?.ephemeral_5m_input_tokens ?? 0;
149	  const split1h = usage.cache_creation?.ephemeral_1h_input_tokens ?? 0;
150	  // The per-TTL split is authoritative where it accounts for the whole write.
151	  // Where it does not — an older record, or a shape this does not know — the
152	  // write bills at the 5-minute rate, which is the API's own default TTL, and
153	  // the discrepancy is recorded rather than rounded away.
154	  const trustSplit = split5m + split1h === written;
155	  if (!trustSplit && written > 0)
156	    warnings.push(
157	      `${response.message.id}: cache_creation split (${split5m} + ${split1h}) does not account for ${written} written tokens; billed at the 5-minute rate`,
158	    );
159	  return {
160	    inputTokens: usage.input_tokens,
161	    cacheWrite5mTokens: trustSplit ? split5m : written,
162	    cacheWrite1hTokens: trustSplit ? split1h : 0,
163	    cacheReadTokens: usage.cache_read_input_tokens ?? 0,
164	    outputTokens: usage.output_tokens,
165	    thinkingTokens: usage.output_tokens_details?.thinking_tokens ?? 0,
166	  };
167	};
168	
169	/**
170	 * Throws when a transcript names a `(model, speed)` pair the table cannot
171	 * price, or an assistant record does not parse: an unpriced response silently
172	 * counted as free is the one failure that makes the whole ledger a lie.
173	 */
174	export const summariseTranscript = (
175	  jsonl: string,
176	  prices: PriceTable,
177	  fallbackSessionId: string,
178	): SessionCost => {
179	  const warnings: string[] = [];
180	  const seen = new Set<string>();
181	  const byRate: Record<string, Tally> = {};
182	  const total = emptyTally();
183	  const ownTurns = emptyTally();
184	  const subagents = emptyTally();
185	  const unpriced = new Set<string>();
186	  const timestamps: string[] = [];
187	  let sessionId: string | undefined;
188	  let branch: string | undefined;
189	  let cwd: string | undefined;
190	
191	  for (const line of jsonl.split('\n')) {
192	    if (line.trim() === '') continue;
193	    const record: unknown = JSON.parse(line);
194	    if (!isResponseRecord(record)) continue;
195	    const response = ResponseRecordSchema.parse(record);
196	    if (seen.has(response.message.id)) continue;
197	    seen.add(response.message.id);
198	
199	    sessionId ??= response.sessionId;
200	    // Last write wins: a session that renames its branch mid-flight should be
201	    // filed under where its work ended up, not where it started.
202	    branch = response.gitBranch ?? branch;
203	    cwd = response.cwd ?? cwd;
204	    if (response.timestamp !== undefined) timestamps.push(response.timestamp);
205	
