  cacheWrite1hTokens: 'cache_write_1h',
  cacheReadTokens: 'cache_read',
  outputTokens: 'output',
} as const satisfies Record<(typeof BILLED_FIELDS)[number], keyof Rates>;

const TOKEN_FIELDS = [
  ...BILLED_FIELDS,
  'thinkingTokens',
] as const satisfies ReadonlyArray<keyof TokenTally>;

const emptyTally = (): Tally => ({
