import assert from 'node:assert/strict';
import { test } from 'node:test';

import { parsePrices, summariseTranscript } from './session-cost.ts';

const prices = parsePrices(
  JSON.stringify({
    as_of: '2026-01-01',
    rates: {
      'test-model/standard': {
        input: 1,
        output: 10,
        cache_write_5m: 2,
        cache_write_1h: 4,
        cache_read: 0.5,
      },
      'test-model/fast': {
        input: 2,
        output: 20,
        cache_write_5m: 4,
        cache_write_1h: 8,
        cache_read: 1,
      },
    },
  }),
);

type UsageOverrides = {
  id?: string;
  speed?: string;
  model?: string;
  sidechain?: boolean;
  input?: number;
  output?: number;
  thinking?: number;
  read?: number;
  write5m?: number;
  write1h?: number;
  written?: number;
};

const response = (overrides: UsageOverrides = {}): string =>
  JSON.stringify({
    type: 'assistant',
    sessionId: 'sess',
    gitBranch: 'a-branch',
    timestamp: '2026-03-04T05:06:07.000Z',
    isSidechain: overrides.sidechain ?? false,
    message: {
      id: overrides.id ?? 'msg_1',
      model: overrides.model ?? 'test-model',
      usage: {
        input_tokens: overrides.input ?? 0,
        output_tokens: overrides.output ?? 0,
        cache_read_input_tokens: overrides.read ?? 0,
        cache_creation_input_tokens:
          overrides.written ??
          (overrides.write5m ?? 0) + (overrides.write1h ?? 0),
        cache_creation: {
          ephemeral_5m_input_tokens: overrides.write5m ?? 0,
          ephemeral_1h_input_tokens: overrides.write1h ?? 0,
        },
        speed: overrides.speed ?? 'standard',
        output_tokens_details: { thinking_tokens: overrides.thinking ?? 0 },
      },
    },
  });

const summarise = (lines: string[]) =>
  summariseTranscript(lines.join('\n'), prices, 'fallback');

test('one response written as several records is counted once', () => {
  // The transcript writes a record per content block — a thinking block and two
  // tool calls make three — each carrying the whole response's usage.
  const cost = summarise([
    response({ output: 1_000_000 }),
    response({ output: 1_000_000 }),
    response({ output: 1_000_000 }),
  ]);
  assert.equal(cost.total.responses, 1);
  assert.equal(cost.total.costUsd, 10);
});

test('cache writes bill by TTL', () => {
  const cost = summarise([
    response({ write5m: 1_000_000, write1h: 1_000_000 }),
  ]);
  assert.equal(cost.total.costUsd, 6);
});

test('speed picks the rate set', () => {
  const standard = summarise([response({ output: 1_000_000 })]);
  const fast = summarise([response({ output: 1_000_000, speed: 'fast' })]);
  assert.equal(fast.total.costUsd, standard.total.costUsd * 2);
});

test('a missing speed reads as standard', () => {
  const line = JSON.parse(response({ output: 1_000_000 })) as {
    message: { usage: Record<string, unknown> };
  };
  delete line.message.usage['speed'];
  const cost = summarise([JSON.stringify(line)]);
  assert.equal(cost.total.costUsd, 10);
  assert.ok('test-model/standard' in cost.byRate);
});

test('thinking tokens are reported but not billed twice', () => {
  const cost = summarise([response({ output: 1_000_000, thinking: 400_000 })]);
  assert.equal(cost.total.thinkingTokens, 400_000);
  assert.equal(cost.total.costUsd, 10);
});

test('subagent responses are split out of the session total', () => {
  const cost = summarise([
    response({ id: 'msg_1', output: 1_000_000 }),
    response({ id: 'msg_2', output: 1_000_000, sidechain: true }),
  ]);
  assert.equal(cost.total.costUsd, 20);
  assert.equal(cost.ownTurns.costUsd, 10);
  assert.equal(cost.subagents.costUsd, 10);
});

test('an unpriced model fails loudly, naming the pair', () => {
  assert.throws(
    () => summarise([response({ model: 'unheard-of' })]),
    /unheard-of\/standard/,
  );
});

test('a cache split that does not account for the write falls back and says so', () => {
  const cost = summarise([
    response({ written: 1_000_000, write5m: 0, write1h: 0 }),
  ]);
  assert.equal(cost.total.cacheWrite5mTokens, 1_000_000);
  assert.equal(cost.total.costUsd, 2);
  assert.match(cost.warnings.join(''), /does not ac{2}ount for 10{6}/);
});

test('records carrying no usage are skipped rather than parsed', () => {
  const cost = summarise([
    JSON.stringify({ type: 'user', message: { content: 'hello' } }),
    JSON.stringify({ type: 'attachment', payload: 42 }),
    response({ output: 1_000_000 }),
  ]);
  assert.equal(cost.total.responses, 1);
});

test('the branch recorded is the one the session ended on', () => {
  const later = JSON.parse(response({ id: 'msg_2' })) as { gitBranch: string };
  later.gitBranch = 'renamed-branch';
  const cost = summarise([response({ id: 'msg_1' }), JSON.stringify(later)]);
  assert.equal(cost.branch, 'renamed-branch');
});

