import json, glob, collections
f = glob.glob('/root/.claude/projects/*/*.jsonl')[0]
seen=set(); kinds=collections.Counter(); tools=collections.Counter()
user_prompts=0
for line in open(f):
    d=json.loads(line)
    if d.get('type')=='user' and not d.get('isSidechain') and isinstance((d.get('message') or {}).get('content'), str):
        user_prompts+=1
    m=d.get('message') or {}
    if not m.get('usage') or m.get('id') in seen: continue
    seen.add(m['id'])
    blocks={b.get('type') for b in m.get('content',[])}
    if 'tool_use' in blocks:
        kinds['ended in a tool call']+=1
        for b in m.get('content',[]):
            if b.get('type')=='tool_use': tools[b.get('name')]+=1
    else:
        kinds['ended in text back to you']+=1
print('API requests total:', len(seen))
for k,v in kinds.items(): print(f'  {k:28} {v:4}  ({100*v/len(seen):.0f}%)')
print()
print('your actual messages in the session:', user_prompts)
print()
print('tool calls by name:')
for name,n in tools.most_common(8): print(f'  {name:12} {n:4}')
PY

