// Reading `--name value` off `process.argv`. What earns a shared home is the
// value form, whose index arithmetic is the same mistake to make twice; a bare
// `includes('--check')` stays where it is written.

export const flag = (name: string): string | undefined => {
  const at = process.argv.indexOf(`--${name}`);
  return at === -1 ? undefined : process.argv[at + 1];
};

export const given = (name: string): boolean =>
  process.argv.includes(`--${name}`);

#!/usr/bin/env node

// Prices one session's transcript and writes its row under `costs/sessions/`.
// The row is rewritten from the whole file each run rather than appended to,
// which is what lets a run pick up what the previous one was too early to see —
// the transcript lags the live conversation.
//
//   node scripts/session-cost.ts --transcript <path> [--session-id <id>] [--row-path]

/* eslint-disable no-console -- stdout is this script's interface: the row's
   path for the hook that calls it, a one-line summary for a person running it
   by hand. */

import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
import path from 'node:path';

import { flag, given } from './lib/argv.ts';
import {
  parsePrices,
  type SessionCost,
  summariseTranscript,
} from './lib/session-cost.ts';

const root = process.env['CLAUDE_PROJECT_DIR'] ?? process.cwd();

const transcript = flag('transcript');
if (transcript === undefined) {
  console.error('session-cost: --transcript <path> is required');
  process.exit(2);
}

// The month a session is filed under is the month it started, so a session
// running across midnight on the last of the month stays in one file.
const monthOf = (cost: SessionCost): string =>
  (cost.firstResponseAt ?? new Date().toISOString()).slice(0, 7);

const prices = parsePrices(
  readFileSync(path.join(root, 'costs/prices.json'), 'utf8'),
);
const cost = summariseTranscript(
  readFileSync(transcript, 'utf8'),
  prices,
  flag('session-id') ?? path.basename(transcript, '.jsonl'),
);

const out = path.join(
  root,
  'costs/sessions',
  monthOf(cost),
  `${cost.sessionId}.json`,
);
mkdirSync(path.dirname(out), { recursive: true });
// Written through a rename so the file is never half-there: the harness's own
// `Stop` hook reads the working tree, and a partial write is a dirty tree.
const staged = `${out}.staged`;
writeFileSync(staged, `${JSON.stringify(cost, null, 2)}\n`);
renameSync(staged, out);

console.log(
  given('row-path')
    ? out
    : `session-cost: ${cost.total.responses} responses, $${cost.total.costUsd.toFixed(4)} → ${out}`,
);

#!/bin/bash
# Sourced by the `UserPromptSubmit` hooks beside it: the payload read, the one
# JSON shape the event accepts, and the guards each of them needs before it can
# do anything.
#
# Every hook sources it as `. "$(dirname "${BASH_SOURCE[0]}")/lib.sh" || exit 0`,
# so a tree holding a hook without this file skips that hook instead of failing
# the turn — the same contract each hook keeps for its own failures. Which is
# also why taking any one hook means taking this file:
# `.claude/skills/update-muthur/catalog.md` has the row saying so.
#
# `need_command` exits the *hook*, not just itself: a sourced function's `exit`
# ends the script that sourced it, which is the intent — a hook with no `jq` has
# nothing to contribute to the turn.

# The event payload, read once — stdin is a pipe, so a second read gets nothing.
# `field` reads what this leaves behind.
read_payload() { payload="$(cat)"; }

field() { jq -r --arg k "$1" '.[$k] // empty' <<<"$payload"; }

# Diagnostics go to stderr under the hook's own name, where the harness surfaces
# them without touching the turn.
say() { echo "$(basename "$0" .sh): $*" >&2; }

need_command() { command -v "$1" >/dev/null || { say "$1 not found; $2"; exit 0; }; }

# True on the prompt a session opens with — the one whose transcript holds
# nothing the agent wrote. `UserPromptSubmit` fires before the prompt is
# recorded, so an assistant record in there means an earlier turn already ran;
# tool results are `user` records too, which is why the agent's own record is the
# mark to grep for. A missing or unreadable transcript reads as a first prompt —
# a firing too many costs a turn's context, a launch slept through costs the
# thing the hook was for.
first_prompt() {
  local transcript
  transcript="$(field transcript_path)"
  [ -n "$transcript" ] || return 0
  ! grep -q '"type":"assistant"' "$transcript" 2>/dev/null
}

# Empty output is the whole signal — a hook that cannot find the tree has no work
# in it — and the status stays 0 so that assigning from this under `set -e` is
# not itself the failure.
project_root() {
  local root="${CLAUDE_PROJECT_DIR:-$(field cwd)}"
  [ -n "$root" ] && [ -d "$root" ] && printf '%s\n' "$root"
  return 0
}

emit_context() {
  jq -n --arg ctx "$1" '{
    hookSpecificOutput: {
      hookEventName: "UserPromptSubmit",
      additionalContext: $ctx
    }
  }'
}

